package com.aiuml.architect.diagram;
import com.fasterxml.jackson.databind.JsonNode; import jakarta.persistence.*; import org.hibernate.annotations.JdbcTypeCode; import org.hibernate.type.SqlTypes; import java.time.Instant; import java.util.UUID;
@Entity @Table(name="diagram_versions",uniqueConstraints=@UniqueConstraint(columnNames={"diagram_id","version_number"})) class DiagramVersionEntity { @Id UUID id; @Column(name="diagram_id",nullable=false) UUID diagramId; @Column(name="version_number",nullable=false) int versionNumber; @JdbcTypeCode(SqlTypes.JSON) @Column(columnDefinition="jsonb",nullable=false) JsonNode document; @Column(name="created_by",nullable=false) UUID createdBy; @Column(nullable=false) Instant createdAt; protected DiagramVersionEntity(){} DiagramVersionEntity(UUID diagramId,int n,JsonNode doc,UUID by){id=UUID.randomUUID();this.diagramId=diagramId;versionNumber=n;document=doc;createdBy=by;createdAt=Instant.now();}}
